(*loader).refine uses (*loader).loadRecursive internally, which may produce a large amount of goroutine as the import graph grows.

With code like following, you can use goroutine only for packages that are ready to load. ([existing code](https://github.com/golang/tools/blob/93eecc3576be04bf4c262289a280dfe13690c317/go/packages/packages.go#L696))

```
// Load type data and syntax if needed, starting at
// the initial packages (roots of the import DAG).
if ld.Mode&NeedTypes != 0 || ld.Mode&NeedSyntax != 0 {
	visited := make(map[*loaderPackage]bool, len(ld.pkgs))
	var visit func(pkg *loaderPackage)
	visit = func(pkg *loaderPackage) {
		for _, imp := range pkg.Imports {
			imp := ld.pkgs[imp.ID]
			if !visited[imp] {
				visited[imp] = true
				visit(imp)
			}
		}
	}
	for _, lpkg := range initial {
		visited[lpkg] = true
		visit(lpkg)
	}

	var wg sync.WaitGroup
	waitNum := make(map[*loaderPackage]*int32, len(visited))
	importedBy := make(map[*loaderPackage][]*loaderPackage, len(visited))

	for lpkg := range visited {
		if !visited[lpkg] {
			continue
		}
		l := int32(len(lpkg.Imports))
		waitNum[lpkg] = &l
		for _, imp := range lpkg.Imports {
			p := ld.pkgs[imp.ID]
			importedBy[p] = append(importedBy[p], lpkg)
		}
	}

	var loadRec func(*loaderPackage)
	loadRec = func(lpkg *loaderPackage) {
		lpkg.loadOnce.Do(func() {
			ld.loadPackage(lpkg)
			for _, lpkg2 := range importedBy[lpkg] {
				if atomic.AddInt32(waitNum[lpkg2], -1) == 0 {
					lpkg2 := lpkg2
					wg.Add(1)
					go func() {
						loadRec(lpkg2)
						wg.Done()
					}()
				}
			}
		})
	}

	for lpkg := range visited {
		if atomic.LoadInt32(waitNum[lpkg]) == 0 {
			lpkg := lpkg
			wg.Add(1)
			go func() {
				loadRec(lpkg)
				wg.Done()
			}()
		}
	}
	wg.Wait()
}
```

VS Code currently does not allow the language server to watch files outside of the workspace root:  https://github.com/microsoft/vscode/issues/100870.

This means that users who open subdirectories of modules or modules with replace directives may see bugs because `gopls`'s view of the workspace state is incorrect.

@heschik has suggested that we should add a work-around to address this -- we could clear out the entire cache when we see >= 10 (or fewer?) batched `didChangeWatchedFiles` notifications. We can do this for any module with a replace directive or for any workspace whose root is not the module root.

